const gaps = $node['Get Content Gaps'].json;
const ourKeywords = $node['Get Our Keywords'].json;

const gapList = Array.isArray(gaps) ? gaps : (gaps?.keyword ? [gaps] : []);
const ourKwList = Array.isArray(ourKeywords) ? ourKeywords : (ourKeywords?.keyword ? [ourKeywords] : []);
const ourKwSet = new Set(ourKwList.map(k => k.keyword?.toLowerCase()));

// Content gaps: keywords competitors rank for but we don't
const contentGaps = gapList.filter(g => g.keyword && !ourKwSet.has(g.keyword.toLowerCase()));

// Categorize gaps
const categories = {};
for (const gap of contentGaps) {
  const keyword = gap.keyword.toLowerCase();
  let category = 'general';

  if (keyword.includes('how to') || keyword.includes('cara') || keyword.includes('tutorial')) category = 'how-to';
  else if (keyword.includes('best') || keyword.includes('top') || keyword.includes('terbaik')) category = 'listicle';
  else if (keyword.includes('vs') || keyword.includes('versus') || keyword.includes('comparison')) category = 'comparison';
  else if (keyword.includes('review') || keyword.includes('ulasan')) category = 'review';
  else if (keyword.includes('what is') || keyword.includes('apa itu')) category = 'definition';
  else if (keyword.includes('price') || keyword.includes('harga') || keyword.includes('cost')) category = 'commercial';

  if (!categories[category]) categories[category] = [];
  categories[category].push(gap);
}

// Priority scoring
const prioritized = contentGaps.map(gap => {
  let priority = 0;
  // Competitor ranks high = more valuable
  if (gap.competitor_position <= 3) priority += 30;
  else if (gap.competitor_position <= 5) priority += 20;
  else if (gap.competitor_position <= 10) priority += 10;

  // We don't rank at all = bigger opportunity
  if (!gap.our_position) priority += 20;
  else if (gap.our_position > 50) priority += 15;

  // Multiple competitors rank = validated topic
  priority += 10;

  return { ...gap, priority_score: priority };
}).sort((a, b) => b.priority_score - a.priority_score);

return [{
  json: {
    total_gaps: contentGaps.length,
    categories: Object.entries(categories).map(([cat, items]) => ({ category: cat, count: items.length })),
    top_opportunities: prioritized.slice(0, 20).map(g => ({
      keyword: g.keyword,
      competitor: g.competitor_domain,
      competitor_position: g.competitor_position,
      our_position: g.our_position || 'Not ranking',
      priority: g.priority_score
    })),
    content_briefs: prioritized.slice(0, 5).map(g => ({
      keyword: g.keyword,
      suggested_title: generateTitle(g.keyword),
      content_type: categorizeKeyword(g.keyword),
      competitor_url: `https://${g.competitor_domain}`,
      target_word_count: g.competitor_position <= 3 ? 2000 : 1500,
      priority: 'high'
    })),
    analyzed_at: new Date().toISOString()
  }
}];

function generateTitle(keyword) {
  const kw = keyword.charAt(0).toUpperCase() + keyword.slice(1);
  if (keyword.includes('how to') || keyword.includes('cara')) return kw + ' - Panduan Lengkap';
  if (keyword.includes('best') || keyword.includes('terbaik')) return kw + ' [Updated 2025]';
  return kw + ' - Semua yang Perlu Anda Ketahui';
}

function categorizeKeyword(keyword) {
  if (keyword.includes('how') || keyword.includes('cara')) return 'guide';
  if (keyword.includes('best') || keyword.includes('top')) return 'listicle';
  if (keyword.includes('vs')) return 'comparison';
  return 'article';
}
